commits.content:
@tailwind base;
@tailwind components;
@tailwind utilities;

v
@layer base {
  :root {
    --plum-500: #9b62b3;
    --plum-700: #6d2b87;
    --plum-200: #dcc8e6;
    --plum-50: #f6eff8;
    --cream: #fffdfb;
    --ink: #29252c;
    --nav-h: 5rem;
  }

  html {
    scroll-behavior: smooth;
    -webkit-text-size-adjust: 100%;
  }

  body {
    @apply bg-cream text-ink font-sans antialiased;
    font-feature-settings: "kern", "liga", "calt";
    overflow-x: hidden;
  }

  ::selection {
    background: var(--plum-200);
    color: var(--plum-700);
  }

  h1, h2, h3, h4 {
    @apply font-serif text-ink;
    text-wrap: balance;
  }

  p {
    text-wrap: pretty;
  }

  :focus-visible {
    outline: 2px solid var(--plum-500);
    outline-offset: 3px;
    border-radius: 2px;
  }

  @media (prefers-reduced-motion: reduce) {
    html { scroll-behavior: auto; }
    *, *::before, *::after {
      animation-duration: 0.01ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.01ms !important;
    }
  }
}

@layer components {
  .container-page {
    @apply mx-auto w-full max-w-page px-5 sm:px-8 lg:px-12;
  }

  /* Small tracked label used sparingly above section titles */
  .kicker {
    @apply font-sans text-[0.68rem] font-medium uppercase tracking-wider2 text-plum-500;
  }

  /* Thin lavender rule with a centered mark */
  .rule {
    @apply relative h-px w-full bg-plum-200;
  }

  /* Editorial drop cap */
  .dropcap::first-letter {
    @apply float-left mr-3 mt-1 font-serif text-[4.6rem] font-medium leading-[0.78] text-plum-700;
  }

  /* Underline that draws in from the left on hover / focus */
  .link-line {
    @apply relative inline-block;
  }
  .link-line::after {
    content: "";
    @apply absolute -bottom-0.5 left-0 h-px w-full origin-right scale-x-0 bg-current transition-transform duration-500 ease-luxe;
  }
  .link-line:hover::after,
  .link-line:focus-visible::after,
  .link-line[aria-current="page"]::after {
    @apply origin-left scale-x-100;
  }

  /* Image hover zoom — applied to the wrapper */
  .zoom-frame {
    @apply relative overflow-hidden bg-plum-50;
  }
  .zoom-frame img {
    @apply transition-transform duration-[1400ms] ease-luxe;
  }
  .zoom-frame:hover img {
    transform: scale(1.04);
  }

  /* Subtle silk texture using the AM brand visual */
  .silk-bg {
    background-image:
      linear-gradient(to bottom, rgba(255, 253, 251, 0.82), rgba(255, 253, 251, 0.94)),
      url("/brand/am-pattern.jpg");
    background-size: cover;
    background-position: center;
  }
  .silk-bg-dark {
    background-image:
      linear-gradient(to bottom, rgba(52, 19, 64, 0.94), rgba(52, 19, 64, 0.97)),
      url("/brand/am-pattern.jpg");
    background-size: cover;
    background-position: center;
  }
}

@layer utilities {
  /* Scroll-triggered reveal (driven by <Reveal />) */
  .reveal {
    opacity: 0;
    transform: translateY(22px);
    transition:
      opacity 1s cubic-bezier(0.22, 1, 0.36, 1),
      transform 1s cubic-bezier(0.22, 1, 0.36, 1);
    transition-delay: var(--reveal-delay, 0ms);
  }
  .reveal.is-visible {
    opacity: 1;
    transform: none;
  }
  .reveal-img {
    clip-path: inset(0 0 100% 0);
    transition: clip-path 1.3s cubic-bezier(0.22, 1, 0.36, 1);
    transition-delay: var(--reveal-delay, 0ms);
  }
  .reveal-img.is-visible {
    clip-path: inset(0 0 0 0);
  }
  @media (prefers-reduced-motion: reduce) {
    .reveal, .reveal-img {
      opacity: 1;
      transform: none;
      clip-path: none;
      transition: none;
    }
  }

  .no-scrollbar::-webkit-scrollbar { display: none; }
  .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }

  .text-balance { text-wrap: balance; }
}
